ex-sentence.code:
def sentence_helper(text, start, end):
    if start >= end:
        return True
    first = text[start]
    last = text[end]
    if not first.isalpha():
        return sentence_helper(text, start + 1, end)
    if not last.isalpha():
        return sentence_helper(text, start, end - 1)
    if first.lower() != last.lower():
        return False
    return sentence_helper(text, start + 1, end - 1)

